 as s(id text,title text,description text,category text,status text,tags jsonb,dataset_ref text)
), imported as (
 insert into public.requests(source_ref,author_id,assignee_id,submission_key,category_id,kind,status,title,description,tags,is_demo,created_at,updated_at,next_step)
 select s.id,a.id,owner.id,gen_random_uuid(),s.category,'problem',s.status::public.request_status,s.title,s.description,
 array(select jsonb_array_elements_text(s.tags)),true,
 now()-(((row_number() over(order by s.id)-1)%28)+1)*interval '1 day',now(),
 case when s.status='in_progress' then 'Проверить повторяющийся сигнал на синтетическом примере.' end
 from samples s
 join auth.users a on a.email='employee@kinetria.example' and a.raw_app_meta_data->>'kinetria_demo'='true'
 join public.profiles author on author.id=a.id and author.active and author.role='employee'
 join auth.users owner on owner.email=case when s.category in('catalog','training') then 'handler@kinetria.example' else 'manager@kinetria.example' end
 and owner.raw_app_meta_data->>'kinetria_demo'='true'
 on conflict(source_ref) do nothing returning id,status,created_at
)
insert into public.request_events(request_id,actor_role,event_type,status,message,created_at)
 select id,'employee','created',status,'Синтетическая вариация датасета заказчика для проверки повторяющихся тем.',created_at from imported;
commit;
